import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadDogriData(){const e=readFileSync(resolve(__dirname,"../../dogri-cinema-explorer/script.js"),"utf-8").replace(/document\.addEventListener\s*\(\s*['"]DOMContentLoaded['"][\s\S]*$/,"");return new Function(e+"\nreturn { DOGRI_CINEMA_INFO, DOGRI_FILMS, DOGRI_ARTISTS, DOGRI_TIMELINE, DOGRI_GALLERY, DOGRI_REFERENCES };")()}describe("Dogri Cinema Explorer — Data Integrity",()=>{let e;beforeAll(()=>{e=loadDogriData()}),describe("DOGRI_CINEMA_INFO metadata",()=>{it("contains correct id and name",()=>{expect(e.DOGRI_CINEMA_INFO.id).toBe("dogri-cinema"),expect(e.DOGRI_CINEMA_INFO.name).toBe("Dogri Cinema")}),it("identifies correct language and region",()=>{expect(e.DOGRI_CINEMA_INFO.language).toBe("Dogri"),expect(e.DOGRI_CINEMA_INFO.region).toContain("Jammu")}),it("references Eighth Schedule correctly",()=>{expect(e.DOGRI_CINEMA_INFO.schedule).toContain("Eighth Schedule")}),it("has at least 3 cultural roots listed",()=>{expect(Array.isArray(e.DOGRI_CINEMA_INFO.culturalRoots)).toBe(!0),expect(e.DOGRI_CINEMA_INFO.culturalRoots.length).toBeGreaterThanOrEqual(3)})}),describe("DOGRI_FILMS dataset",()=>{it("contains exactly 6 notable film entries",()=>{expect(Array.isArray(e.DOGRI_FILMS)).toBe(!0),expect(e.DOGRI_FILMS.length).toBe(6)}),it("every film entry has required fields: id, title, year, genre, significance",()=>{e.DOGRI_FILMS.forEach((e,t)=>{expect(e,`Film ${t} missing id`).toHaveProperty("id"),expect(e,`Film ${t} missing title`).toHaveProperty("title"),expect(e,`Film ${t} missing year`).toHaveProperty("year"),expect(e,`Film ${t} missing genre`).toHaveProperty("genre"),expect(e,`Film ${t} missing significance`).toHaveProperty("significance"),expect(typeof e.title).toBe("string"),expect(e.title.trim().length).toBeGreaterThan(0),expect(typeof e.year).toBe("number")})}),it("first film is from the 1980s (pioneer era)",()=>{const t=e.DOGRI_FILMS[0];expect(t.year).toBeGreaterThanOrEqual(1980),expect(t.year).toBeLessThan(1990)}),it("films are in approximate chronological order",()=>{for(let t=0;t<e.DOGRI_FILMS.length-1;t++)expect(e.DOGRI_FILMS[t].year).toBeLessThanOrEqual(e.DOGRI_FILMS[t+1].year)})}),describe("DOGRI_ARTISTS dataset",()=>{it("contains at least 4 pioneering artists",()=>{expect(Array.isArray(e.DOGRI_ARTISTS)).toBe(!0),expect(e.DOGRI_ARTISTS.length).toBeGreaterThanOrEqual(4)}),it("every artist has id, name, role, and contribution fields",()=>{e.DOGRI_ARTISTS.forEach((e,t)=>{expect(e,`Artist ${t} missing id`).toHaveProperty("id"),expect(e,`Artist ${t} missing name`).toHaveProperty("name"),expect(e,`Artist ${t} missing role`).toHaveProperty("role"),expect(e,`Artist ${t} missing contribution`).toHaveProperty("contribution"),expect(typeof e.name).toBe("string"),expect(e.name.trim().length).toBeGreaterThan(0)})}),it("includes Padma Sachdev as a cultural icon",()=>{const t=e.DOGRI_ARTISTS.find(e=>e.name.includes("Padma Sachdev"));expect(t).toBeDefined(),expect(t.contribution).toMatch(/Sahitya Akademi/i)})}),describe("DOGRI_TIMELINE dataset",()=>{it("contains exactly 5 timeline eras",()=>{expect(Array.isArray(e.DOGRI_TIMELINE)).toBe(!0),expect(e.DOGRI_TIMELINE.length).toBe(5)}),it("every timeline entry has id, period, era, and description",()=>{e.DOGRI_TIMELINE.forEach((e,t)=>{expect(e,`Timeline ${t} missing id`).toHaveProperty("id"),expect(e,`Timeline ${t} missing period`).toHaveProperty("period"),expect(e,`Timeline ${t} missing era`).toHaveProperty("era"),expect(e,`Timeline ${t} missing description`).toHaveProperty("description"),expect(typeof e.era).toBe("string"),expect(e.era.trim().length).toBeGreaterThan(0)})}),it("first era is the 1960s–1970s cultural roots period",()=>{expect(e.DOGRI_TIMELINE[0].period).toContain("1960")}),it("last era references digital/OTT platforms",()=>{const t=e.DOGRI_TIMELINE[e.DOGRI_TIMELINE.length-1];expect(t.description).toMatch(/OTT|digital|streaming/i)})}),describe("DOGRI_GALLERY dataset",()=>{it("has exactly 4 gallery items",()=>{expect(Array.isArray(e.DOGRI_GALLERY)).toBe(!0),expect(e.DOGRI_GALLERY.length).toBe(4)}),it("every gallery item has id, title, and subtitle",()=>{e.DOGRI_GALLERY.forEach((e,t)=>{expect(e,`Gallery ${t} missing id`).toHaveProperty("id"),expect(e,`Gallery ${t} missing title`).toHaveProperty("title"),expect(e,`Gallery ${t} missing subtitle`).toHaveProperty("subtitle")})})}),describe("DOGRI_REFERENCES dataset",()=>{it("contains at least 4 references",()=>{expect(Array.isArray(e.DOGRI_REFERENCES)).toBe(!0),expect(e.DOGRI_REFERENCES.length).toBeGreaterThanOrEqual(4)}),it("every reference has id, source, and title",()=>{e.DOGRI_REFERENCES.forEach((e,t)=>{expect(e,`Reference ${t} missing id`).toHaveProperty("id"),expect(e,`Reference ${t} missing source`).toHaveProperty("source"),expect(e,`Reference ${t} missing title`).toHaveProperty("title")})}),it("includes NFAI as a reference",()=>{const t=e.DOGRI_REFERENCES.find(e=>e.source.includes("NFAI")||e.source.includes("National Film Archive"));expect(t).toBeDefined()})})});